class Solution:
    def threeSumClosest(self, nums: List[int], target: int) -> int:
        closest = float('inf')
        nums.sort() #O(N*LogN)
        n = len(nums)
        for i in range(n-2): #O(N)
            left, right = i + 1, n - 1 
            while left < right : #O(N^2)
                total = nums[i] + nums[left] + nums[right]
                if abs(total - target ) < abs(closest - target):
                    closest = total

                if total < target:
                    left += 1
                elif total > target:
                    right -= 1 
                else:
                    return target

        return closest

class Solution:
    def merge(self, nums1: List[int], m: int, nums2: List[int], n: int) -> None:
        i = 0
        j = 0
        result = []
        while i < m and j < n :
            if nums1[i] <= nums2[j]:
                result.append(nums1[i])
                i += 1
            else:
                result.append(nums2[j])
                j += 1
        while i < m :
            result.append(nums1[i])
            i += 1
        while j < n :
            result.append(nums2[j])
            j += 1
        for k in range(len(result)):
            nums1[k] = result[k]

class Solution:
    def findPeakElement(self, nums: List[int]) -> int:
        low = 0
        high = len(nums) - 1 
        while low < high :
            mid = (low + high) // 2

            if nums[mid] > nums[mid + 1]:
                high = mid
            else:
                low = mid + 1
        return low

