class Solution:
    def fairCandySwap(self, aliceSizes: List[int], bobSizes: List[int]) -> List[int]:
        aliceSizes.sort()
        bobSizes.sort()
        i = j = 0
        target = (sum(bobSizes) - sum(aliceSizes)) // 2
        while i < len(aliceSizes) and j < len(bobSizes) :
            curr = bobSizes[j] - aliceSizes[i]

            if curr == target:
                return [aliceSizes[i],bobSizes[j]]
            elif curr < target:
                j += 1
            else:
                i += 1
        return []

class Solution:
    def repeatedNTimes(self, nums: List[int]) -> int:
        freq = Counter(nums)
        ans = 0
        target = (len(nums)) / 2
        for key, value in freq.items():
            if value >= target:
                ans = max(ans,key) 
        return ans

class Solution:
    def carPooling(self, trips: List[List[int]], capacity: int) -> bool:
        timeline = [0] * 1002
        for passanger, start, end in trips:
            timeline[start] += passanger
            timeline[end] -= passanger
        seats = 0
        for passanger_change in timeline:
            seats += passanger_change 
            if seats > capacity:
                return False
        return True

class Solution:
    def maxNumberOfBalloons(self, text: str) -> int:
        count = {'b':0,'a':0,'l':0,'n':0,'o':0}

        for char in text:
            if char in count:
                count[char] += 1

        return min (
            count['b'],count['a'],count['l'] // 2,count['n'],count['o']//2
    )

