class Solution:
    def checkIfExist(self, arr: List[int]) -> bool:
        seen = set()
        for num in arr:
            if num * 2 in seen or (num % 2 == 0 and num // 2 in seen):
                return True
            seen.add(num)
        return False

class Solution:
    def countNegatives(self, grid: List[List[int]]) -> int:
        rows = len(grid)
        elements = len(grid[0])
        i = rows - 1
        j = 0
        count = 0
        while i >=0 and j < elements:
            if grid[i][j] < 0:
                count += elements - j
                i -= 1
            else:
                j += 1

        return count

class Solution:
    def findTheDistanceValue(self, arr1: List[int], arr2: List[int], d: int) -> int:
        arr1.sort(),arr2.sort()
        i = j = 0
        count = 0 
        while i < len(arr1) and j < len(arr2):
            if abs(arr1[i] - arr2[j]) <= d:
                i += 1
            elif arr1[i] > arr2[j]:
                j += 1
            else:
                i += 1
                count += 1
        if i < len(arr1):
            count += len(arr1) - i
        return count

class Solution:
    def maxCoins(self, piles: List[int]) -> int:
        piles.sort()
        n = len(piles)
        starter = n // 3 
        result = 0
        while starter < n :
            result += piles[starter]
            starter += 2
        return result

class Solution:
    def frequencySort(self, nums: List[int]) -> List[int]:
        frequency = {}
        for num in nums :
            if num in frequency:
                frequency[num] += 1
            else:
                frequency[num] = 1
        return sorted(nums,key = lambda x : (frequency[x],-x))

class Solution:
    def maxWidthOfVerticalArea(self, points: List[List[int]]) -> int:
        diff = 0
        points.sort()
        for i in range(1,len(points)):
            diff = max(diff, points[i][0] - points[i-1][0])
