class Solution:
    def pivotArray(self, nums: List[int], pivot: int) -> List[int]:
        smaller = []
        equal = []
        larger = []
        for num in nums :
            if num < pivot :
                smaller.append(num)
            elif num == pivot :
                equal.append(num)
            else:
                larger.append(num)
        return smaller + equal + larger

class Solution:
    def countOperations(self, num1: int, num2: int) -> int:
        operations = 0
        while num1>0 and num2>0:
            if num1 >= num2:
                num1 -= num2
            else:
                num2 -= num1
            operations += 1
        return operations

class Solution:
    def mostFrequent(self, nums: List[int], key: int) -> int:
        freq = {}
        for i in range(len(nums) -1):
            if nums[i] == key:
                target = nums[i+1]
                freq[target] = freq.get(target,0) + 1
        mx = 0
