class Solution:
    def maximumCount(self, nums: List[int]) -> int:
        pos = neg = zero = 0
        for num in nums :
            if num == 0:
                zero += 1
            elif num > 0:
                pos += 1
            else:
                neg += 1
        return max(pos,neg)

class Solution:
    def getCommon(self, nums1: List[int], nums2: List[int]) -> int:
        i = j = 0
        while i < len(nums1) and j < len(nums2):
            if nums1[i] == nums2[j]:
                return nums1[i]
            elif nums1[i] < nums2[j]:
                i += 1
            else:
                j += 1
        return -1

