class Solution:
    def isGood(self, nums: List[int]) -> bool:
        n = len(nums) - 1
        seen = set()
        duplicate = False
        for num in nums:
            if num > n :
                return False
            if num in seen :
                if num < n or duplicate:
                    return False
                duplicate =True 
                continue
            seen.add(num)
        return True

class Solution:
    def countPairs(self, nums: List[int], target: int) -> int:
        nums.sort()
        low = count = 0
        high = len(nums) - 1 
        while low < high :
            if (nums[low] + nums[high] < target):
                count += high - low
                low += 1  
            else:
                high -= 1
        return count

class Solution:
    def sumCounts(self, nums: List[int]) -> int:
        Sum = 0
        for i in range(len(nums)):
            for j in range(i+1, len(nums) + 1):
                subarray = nums[i:j]
