class Solution:
    def maxFrequencyElements(self, nums: List[int]) -> int:
        freq = {}
        for num in nums:
            if num in freq:
                freq[num] += 1
            else:
                freq[num] = 1
        max_freq = 0
        for count in freq.values():
            if count > max_freq:
                max_freq = count
        total_max_freq_element = 0
        for count in freq.values():
            if count == max_freq:
                total_max_freq_element += count
        return total_max_freq_element

class Solution:
    def maximumLength(self, nums: List[int]) -> int:
        counts = {}
        for num in nums:
            counts[num] = counts.get(num, 0) + 1

        max_len = 1

        # 2. Handle the special case for '1'
        if 1 in counts:
            ones = counts[1]
            if ones % 2 == 0:
                ones -= 1
            max_len = max(max_len, ones)

        # 3. Iterate through the unique numbers in our dictionary
        for num in counts:
            if num == 1:
                continue

            curr = num
            curr_len = 0

            # Use .get(curr, 0) to avoid KeyErrors if the square doesn't exist
            while counts.get(curr, 0) >= 2 and counts.get(curr**2, 0) >= 1:
                curr_len += 2       # Add one to the left, one to the right
                curr = curr**2      # Move up to the next square

            # Add the peak element
            curr_len += 1

            # Update the global maximum
            max_len = max(max_len, curr_len)

        return max_len

class Solution:
    def numberOfPairs(self, nums1: List[int], nums2: List[int], k: int) -> int:
        count = 0
        for i in range(len(nums1)):
            for j in range(len(nums2)):
                if (nums1[i] % (nums2[j] * k)) == 0 :
                    count += 1
        return count

class Solution:
    def transformArray(self, nums: List[int]) -> List[int]:
        result = []

        for num in nums:
            if num % 2 == 0:
                result.append(0)
            else:
                result.append(1)

        low = mid = 0
        high = len(result) - 1

        while mid <= high:
            if result[mid] == 0:
                result[low], result[mid] = result[mid], result[low]
                low += 1
                mid += 1
            else:  # result[mid] == 1
                mid += 1

        return result

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        count = 0
        for fruit in fruits :
            placed = False
            for j in range(len(baskets)):
                if baskets[j] >= fruit:
                    baskets[j] = -1
                    placed = True
                    break

            if not placed:
                count += 1

        return count

class Solution:
    def earliestFinishTime(self, landStartTime: List[int], landDuration: List[int], waterStartTime: List[int], waterDuration: List[int]) -> int:
        minLand1 = float('inf')
        for i in range(len(landStartTime)):
            minLand1 = min(minLand1, landStartTime[i] + landDuration[i])

        result1 = float('inf')
        for i in range(len(waterStartTime)):
            waterStart = max(minLand1, waterStartTime[i])
            result1 = min(result1, waterStart + waterDuration[i])

        minWater2 = float('inf')
        for i in range(len(waterStartTime)):
            minWater2 = min(minWater2, waterStartTime[i] + waterDuration[i])

        result2 = float('inf')
        for i in range(len(landStartTime)):
            landStart = max(minWater2, landStartTime[i])
            result2 = min(result2, landStart + landDuration[i])

        return min(result1, result2)

class Solution:
    def sumAndMultiply(self, n: int) -> int:
        n_str = str(n)

        x_str = "".join(digit for digit in n_str if digit != '0')

        if not x_str:
            x = 0
            sum_of_digits = 0
        else:
            x = int(x_str)
            sum_of_digits = sum(int(digit) for digit in x_str)

        result = x * sum_of_digits
        return result

class Solution:
    def digitFrequencyScore(self, n: int) -> int:
        frequency = {}
        for ch in str(n):
            digits = int(ch)
            frequency[digits] = frequency.get(digits,0) + 1
        score = 0
        for digit, count in frequency.items():
            score += digit * count
        return score
